import{_ as e,o as a,c as l,a2 as i}from"./chunks/framework.ClgMjOt7.js";const g=JSON.parse('{"title":"インストールガイド","description":"動作環境、パーミッション権限、F-Droid および GitHub からのインストール手順","frontmatter":{"title":"インストールガイド","description":"動作環境、パーミッション権限、F-Droid および GitHub からのインストール手順"},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":1786168778000}'),d={name:"guide/installation.md"};function s(r,t,o,n,c,h){return a(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="インストールガイド" tabindex="-1">インストールガイド <a class="header-anchor" href="#インストールガイド" aria-label="Permalink to &quot;インストールガイド&quot;">​</a></h1><h2 id="動作要件" tabindex="-1">動作要件 <a class="header-anchor" href="#動作要件" aria-label="Permalink to &quot;動作要件&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">項目</th><th style="text-align:left;">条件 / 仕様</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>OS バージョン</strong></td><td style="text-align:left;">Android 10 (API Level 29) 以上</td></tr><tr><td style="text-align:left;"><strong>ターゲット SDK</strong></td><td style="text-align:left;">Android 14 (API Level 34)</td></tr><tr><td style="text-align:left;"><strong>アカウント</strong></td><td style="text-align:left;">Pixiv アカウント (ログイン時)</td></tr><tr><td style="text-align:left;"><strong>ネットワーク</strong></td><td style="text-align:left;">インターネット接続環境</td></tr></tbody></table><hr><h2 id="必要なアプリ権限-permissions" tabindex="-1">必要なアプリ権限 (Permissions) <a class="header-anchor" href="#必要なアプリ権限-permissions" aria-label="Permalink to &quot;必要なアプリ権限 (Permissions)&quot;">​</a></h2><p>Palleria が要求する権限と使用目的は以下の通りです。</p><table tabindex="0"><thead><tr><th style="text-align:left;">権限名</th><th style="text-align:left;">目的</th></tr></thead><tbody><tr><td style="text-align:left;"><code>INTERNET</code></td><td style="text-align:left;">Pixiv API との通信および画像データのダウンロード</td></tr><tr><td style="text-align:left;"><code>ACCESS_NETWORK_STATE</code></td><td style="text-align:left;">Wi-Fi 接続状態の検知 (Wi-Fi のみダウンロード設定等)</td></tr><tr><td style="text-align:left;"><code>WRITE_EXTERNAL_STORAGE</code></td><td style="text-align:left;">画像データのローカルストレージ保存 (Android 9 以下互換)</td></tr><tr><td style="text-align:left;"><code>READ_MEDIA_IMAGES</code></td><td style="text-align:left;">保存済み画像の読み込みおよびライブ壁紙ソース参照 (Android 13+)</td></tr><tr><td style="text-align:left;"><code>USE_BIOMETRIC</code> / <code>USE_FINGERPRINT</code></td><td style="text-align:left;">生体認証（指紋/顔認証）によるアプリロック解除</td></tr><tr><td style="text-align:left;"><code>POST_NOTIFICATIONS</code></td><td style="text-align:left;">ダウンロード進捗通知および自動同期通知の表示</td></tr><tr><td style="text-align:left;"><code>SET_WALLPAPER</code></td><td style="text-align:left;">ライブ壁紙サービスによる壁紙の変更設定</td></tr></tbody></table><hr><h2 id="インストール手順" tabindex="-1">インストール手順 <a class="header-anchor" href="#インストール手順" aria-label="Permalink to &quot;インストール手順&quot;">​</a></h2><h3 id="_1-f-droid-リポジトリ経由-推奨" tabindex="-1">1. F-Droid リポジトリ経由 (推奨) <a class="header-anchor" href="#_1-f-droid-リポジトリ経由-推奨" aria-label="Permalink to &quot;1. F-Droid リポジトリ経由 (推奨)&quot;">​</a></h3><p>F-Droid クライアントまたは Droid-ify 等のサードパーティストア経由でインストール・更新できます。</p><p>リポジトリ URL:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://yunfi.f5.si/Palleria/repo/</span></span></code></pre></div><p>リポジトリの SHA-256 フィンガープリント:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>28A7F64F373AC1AD5FBB4822870E2E07B2B204C7EC71E58CE40F9D54EF2727D9</span></span></code></pre></div><ol><li>F-Droid アプリの「設定」&gt;「リポジトリ」&gt;「追加」を開きます。</li><li>上記のリポジトリ URL を入力（または QR コード読み取り）して追加します。</li><li>リポジトリの同期完了後、検索窓で <code>Palleria</code> を検索してインストールします。</li></ol><hr><h3 id="_2-github-releases-経由-単体-apk" tabindex="-1">2. GitHub Releases 経由 (単体 APK) <a class="header-anchor" href="#_2-github-releases-経由-単体-apk" aria-label="Permalink to &quot;2. GitHub Releases 経由 (単体 APK)&quot;">​</a></h3><p><a href="https://github.com/yunfie-twitter/Palleria/releases/latest" target="_blank" rel="noreferrer">GitHub Releases</a> ページから直接 APK ファイルを入手して手動インストールします。</p><ol><li>最新リリースの <code>Assets</code> から <code>Illustia-v5.0.0-release.apk</code>（または最新バージョンの APK）をダウンロードします。</li><li>ダウンロードした APK をタップして開きます。</li><li>ダイアログが表示された場合、「設定」をタップして「このソースからのアプリを許可」を有効にしてインストールを実行します。</li></ol><div class="info custom-block"><p class="custom-block-title">自動更新確認</p><p>GitHub 直接インストールの場合でも、アプリ内の「設定」&gt;「バージョン情報」から最新リリースの有無を確認し、更新ファイルを読み込むことができます。</p></div>',21)])])}const f=e(d,[["render",s]]);export{g as __pageData,f as default};
